mapper.select:
SELECT id, name, description, monitor_type, scope_type, scope_id, enabled, severity,
       config_json, min_consecutive_breaches, suppressed_by_monitor_id, created_by,
       created_time, updated_by, updated_time
FROM sentinel_monitor

    AND scope_type = #{scopeType}
    AND monitor_type = #{monitorType}
    AND enabled = #{enabled}
    AND scope_id = #{scopeId}

ORDER BY name

