SELECT id, monitor_id, channel_id, metadata_id, state, consecutive_breach_count,
       last_value_json, open_alert_event_id, last_change_time, last_evaluated_time
FROM sentinel_trigger_state
WHERE monitor_id = #{monitorId} AND channel_id = #{channelId}
AND metadata_id = #{metadataId}
AND metadata_id IS NULL

